with a as (insert into automations (user_id,workspace_id,name,description,trigger_type,trigger_event,trigger_source,trigger_config,status,exit_criteria,enrollment_object_type,enrollment_method,filter_groups,reenrollment_config)
select 'afd12255-5ad7-46f9-8588-c51cf1ed1f72','95bc7e99-798e-49ef-a5c3-ab68bbc08950','Facebook Ad Lead → AI Video Course Nurture','Starts when a lead is tagged ai-video-ad-lead (Facebook/Instagram ad leads). Sends the course link and follow-ups until they buy.','lead_tagged','lead_tagged','crm','{"tags": "ai-video-ad-lead"}'::jsonb,'active','[{"type": "unsubscribed"}, {"type": "tag_added", "tag": "ai-video-production-for-small-businesses"}]'::jsonb,'lead','automatic','[]'::jsonb,'{"mode": "never"}'::jsonb
where not exists (select 1 from automations where workspace_id='95bc7e99-798e-49ef-a5c3-ab68bbc08950' and name='Facebook Ad Lead → AI Video Course Nurture') returning id)
insert into automation_steps (automation_id,workspace_id,step_order,step_type,config)
select a.id,'95bc7e99-798e-49ef-a5c3-ab68bbc08950'::uuid,x.o,x.t,x.c from a,(values
(0,'action','{"action":"send_email","subject":"Your link: AI Video Production for Small Businesses","body":"Hi {{first_name}},\n\nThanks for your interest in AI Video Production for Small Businesses from our Facebook/Instagram ad.\n\nHere is the direct link to view the course and secure your place:\n\n<a href=\"https://nexusflo24.com/academy/ai-video-production-for-small-businesses\" style=\"display:inline-block;background:#0B1F3B;color:#ffffff;padding:14px 32px;font-weight:600;text-decoration:none;border-radius:8px\">View the course & enrol</a>\n\nOnce you enrol, you will pick your live class time straight away.\n\nBest regards,\nKizito Adichie\nNexusFlo24 Academy"}'::jsonb),
(1,'delay','{"duration":1,"unit":"days"}'::jsonb),
(2,'action','{"action":"send_email","subject":"What you will create in AI Video Production","body":"Hi {{first_name}},\n\nIn this course you will learn to:\n\n1. Script short videos that sell\n2. Create studio-quality videos with AI, no camera crew needed\n3. Turn them into ads and social posts for your business\n\nPlus a live practical class where we build your videos together.\n\n<a href=\"https://nexusflo24.com/academy/ai-video-production-for-small-businesses\" style=\"color:#0B1F3B;text-decoration:underline\">See the full course and enrol</a>\n\nKizito"}'::jsonb),
(3,'delay','{"duration":2,"unit":"days"}'::jsonb),
(4,'action','{"action":"notify_sales","title":"Ad lead hasn''t enrolled yet","message":"{{first_name}} {{last_name}} came from the AI Video course ad 3 days ago and hasn''t bought. A quick WhatsApp or call could close it."}'::jsonb),
(5,'action','{"action":"send_email","subject":"Any questions about the AI Video course?","body":"Hi {{first_name}},\n\nI noticed you haven''t enrolled yet, so I wanted to check if you have any questions. Just reply to this email and I will personally get back to you.\n\n<a href=\"https://nexusflo24.com/academy/ai-video-production-for-small-businesses\" style=\"color:#0B1F3B;text-decoration:underline\">Secure your place</a>\n\nKizito"}'::jsonb),
(6,'delay','{"duration":3,"unit":"days"}'::jsonb),
(7,'action','{"action":"send_email","subject":"Last reminder: live class places for AI Video Production","body":"Hi {{first_name}},\n\nThis is my last reminder about AI Video Production for Small Businesses. Live class places are limited.\n\n<a href=\"https://nexusflo24.com/academy/ai-video-production-for-small-businesses\" style=\"display:inline-block;background:#0B1F3B;color:#ffffff;padding:14px 32px;font-weight:600;text-decoration:none;border-radius:8px\">Enrol now</a>\n\nBest regards,\nKizito Adichie"}'::jsonb),
(8,'action','{"action":"add_tag","tag":"ai-video-ad-nurture-completed"}'::jsonb)
) as x(o,t,c);